// Get the JSON object from the previous node
const masterData = $input.first().json;

// Map the keys into a standard array n8n can handle
return Object.keys(masterData).map(key => {
  return {
    name: key,
    // Handle the nested NVD URL specifically if needed, 
    // or just pass the whole value
    url: typeof masterData[key] === 'string' ? masterData[key] : "https://nvd.nist.gov/feeds/xml/cve/misc/nvd-rss.xml" 
  };
});
